import{_ as d,o as c,c as o,a3 as t}from"./chunks/framework.DAK02U1-.js";const g=JSON.parse('{"title":"CMake API","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"CMake API | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/zh/xclang/reference/cmake-api"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"zh_CN"}],["link",{"rel":"canonical","href":"https://docs.clice.io/zh/xclang/reference/cmake-api"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/reference/cmake-api"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/reference/cmake-api"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/xclang/reference/cmake-api"}]]},"headers":[],"relativePath":"zh/xclang/reference/cmake-api.md","filePath":"zh/xclang/reference/cmake-api.md","lastUpdated":1794509097000}'),a={name:"zh/xclang/reference/cmake-api.md"};function l(n,e,i,r,s,_){return c(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="cmake-api" tabindex="-1">CMake API <a class="header-anchor" href="#cmake-api" aria-label="Permalink to &quot;CMake API&quot;">​</a></h1><p>本页列出 xclang 的 CMake 包定义的所有内容。具体用法见 <a href="./../integrations/cmake">CMake</a>。</p><p>CMake 包位于每个工具链目录（以及 conda 软件包）的 <code>lib/cmake/xclang</code> 下，同时也位于代码仓库各个版本标签的 <code>packages/cmake/</code> 下。它要求 CMake 3.28 及以上；构建 C++20 模块时还要求使用 Ninja 或 Ninja Multi-Config 生成器，且 Ninja 版本为 1.11 及以上。</p><h2 id="文件" tabindex="-1">文件 <a class="header-anchor" href="#文件" aria-label="Permalink to &quot;文件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文件</th><th>说明</th></tr></thead><tbody><tr><td><code>xclang-config.cmake</code></td><td>供 <code>find_package(xclang)</code> 加载：定义 <code>xclang::std</code>、<code>xclang_add_std()</code>、<code>xclang_debug_symbols()</code>、<code>XCLANG_ROOT</code> 以及 ThinLTO 缓存配置</td></tr><tr><td><code>xclang-config-version.cmake</code></td><td>记录版本号，供 <code>find_package(xclang 23.1)</code> 匹配版本（仅存在于工具链压缩包中）</td></tr><tr><td><code>toolchain.cmake</code></td><td>将工具链目录设为当前构建的工具链，面向主机或 <code>XCLANG_TARGET</code></td></tr><tr><td><code>runtimes.cmake</code></td><td>由 <code>toolchain.cmake</code> 引入：负责从源码构建运行时库以及配置构建所用的 sanitizer</td></tr><tr><td><code>runtimes-cxx.cmake</code>, <code>runtimes-compiler-rt.cmake</code></td><td>xclang 自身构建 libc++ 与 compiler-rt 时使用的 CMake 缓存文件，供 <code>runtimes.cmake</code> 构建运行时库使用（仅存在于工具链压缩包中）</td></tr><tr><td><code>xclang.cmake</code></td><td>仅位于 <code>packages/cmake/</code> 下：通过 FetchContent 检出后在 <code>project()</code> 之前引入，负责自动下载工具链</td></tr></tbody></table><h2 id="find-package-xclang" tabindex="-1"><code>find_package(xclang)</code> <a class="header-anchor" href="#find-package-xclang" aria-label="Permalink to &quot;`find_package(xclang)`&quot;">​</a></h2><p>需在 <code>project()</code> 或 <code>enable_language(CXX)</code> 之后调用，且构建所用的 C++ 编译器必须是 xclang 的 <code>clang++</code>。它会通过 <code>PATH</code>（由 <code>$XCLANG/bin</code> 推导至 <code>$XCLANG/lib/cmake/xclang</code>）、<code>xclang_ROOT</code> 或 <code>CMAKE_PREFIX_PATH</code> 查找包。</p><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th></th></tr></thead><tbody><tr><td><code>xclang::std</code></td><td>CMake 目标</td><td>针对当前构建目标平台的 libc++ <code>std</code> 与 <code>std.compat</code> 模块静态库（启用 <code>-stdlib=platform</code> 或 <code>XCLANG_STDLIB=platform</code> 时则为平台标准库的模块，如 MSVC 目标平台上的微软 STL）；仅当被其他目标链接时才会实际编译（<a href="./../features/modules#cmake">语言选项</a>）</td></tr><tr><td><code>xclang_add_std(&lt;name&gt;)</code></td><td>函数</td><td>创建另一个标准库模块目标；其上的 <code>PUBLIC</code> 编译选项会传递给所有 import 它的目标</td></tr><tr><td><code>xclang_debug_symbols(&lt;program&gt; [GSYM_ARGS &lt;option&gt;...])</code></td><td>函数</td><td>在每次链接 CMake 目标 <code>&lt;program&gt;</code> 后：调用单线程的 llvm-gsymutil 在其旁生成 <code>&lt;program&gt;.gsym</code>（每次运行产出逐字节相同的文件，<code>GSYM_ARGS</code> 追加在 <code>--num-threads=1</code> 之后），并将日志输出到 <code>&lt;program&gt;.gsym.log</code>；在 macOS 目标平台上会先生成 <code>&lt;program&gt;.dSYM</code>（<a href="./../features/debugging#usage">调试</a>）；在 MSVC 目标平台上不执行任何操作，由链接步骤直接写出 PDB</td></tr><tr><td><code>XCLANG_ROOT</code></td><td>变量</td><td>工具链目录</td></tr><tr><td><code>XCLANG_THINLTO_CACHE</code></td><td>缓存变量</td><td>链接器 ThinLTO 缓存目录的绝对路径；初始值取自同名环境变量（<a href="./../features/libclang#the-thinlto-cache">ThinLTO 缓存</a>）</td></tr></tbody></table><p><code>xclang::std</code> 要求 import 它的目标使用 C++23（若构建它时所在目录的 <code>CMAKE_CXX_STANDARD</code> 为 20 或更高，则要求对应的标准版本）。设置 <code>XCLANG_RUNTIMES=source</code> 时，它会基于从源码构建的运行时库变体的模块源码与头文件编译；这一选项必须配合工具链文件使用，否则 <code>find_package(xclang)</code> 会报错失败。</p><h2 id="toolchain-cmake" tabindex="-1"><code>toolchain.cmake</code> <a class="header-anchor" href="#toolchain-cmake" aria-label="Permalink to &quot;`toolchain.cmake`&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cmake -G Ninja -B build --toolchain $XCLANG/lib/cmake/xclang/toolchain.cmake [-DXCLANG_TARGET=&lt;target&gt;]</span></span></code></pre></div><table tabindex="0"><thead><tr><th>变量</th><th></th></tr></thead><tbody><tr><td><code>XCLANG_TARGET</code></td><td>可选 <code>x86_64-unknown-linux-gnu</code>、<code>aarch64-unknown-linux-gnu</code>、<code>x86_64-unknown-linux-musl</code>、<code>aarch64-unknown-linux-musl</code>、<code>x86_64-w64-mingw32</code>、<code>aarch64-w64-mingw32</code>、<code>aarch64-apple-darwin</code>、<code>x86_64-apple-darwin</code>、<code>x86_64-pc-windows-msvc</code> 或 <code>aarch64-pc-windows-msvc</code>，默认为当前主机。MSVC 目标平台以及在 Linux 和 Windows 主机上构建的 macOS 目标平台会使用由工具链 <code>xclang</code> 命令下载的 SDK；未下载 SDK 的 Windows 主机在构建 MSVC 目标平台时则会使用本机安装的 Visual Studio。在同架构的 Linux 主机上构建 musl 目标平台不视为交叉编译，主机可直接运行其生成的静态程序（<code>try_run</code> 与测试）。构建目录会固定首次配置时的目标平台，后续若改为其他目标平台则会停止配置（请换用新构建目录或运行 <code>cmake --fresh</code>）</td></tr><tr><td><code>XCLANG_ROOT</code></td><td>工具链目录，在工具链目录之外使用工具链文件时需指定；相对路径相对于构建目录解析</td></tr><tr><td><code>XCLANG_STDLIB</code></td><td>默认为 <code>libc++</code>：使用 xclang 的 libc++ 及内置 sysroot。设为 <code>platform</code> 时：使用平台的 C++ 标准库，向每次编译和链接传入 <code>-stdlib=platform</code>（<a href="./../integrations/cmake#use-the-system-s-c-library">使用系统的 C++ 标准库</a>）；Linux 目标平台不再设置指向工具链的 <code>CMAKE_SYSROOT</code>，musl 与 MinGW 目标平台则要求用户自行指定 sysroot；当平台标准库带有模块清单（如 GCC 15 的 libstdc++）时，<code>xclang::std</code> 使用平台标准库的模块，否则 <code>find_package(xclang)</code> 会报错失败。不可与 <code>XCLANG_RUNTIMES=source</code> 同时使用</td></tr><tr><td><code>XCLANG_RUNTIMES</code>, <code>XCLANG_SANITIZER</code>, ...</td><td>从源码构建运行时库及构建所用的 sanitizer 选项（<a href="#runtimes-from-source">见下文</a>）</td></tr></tbody></table><p>它会将 C、C++ 与汇编编译器以及各二进制工具设为工具链目录中的对应程序：<code>llvm-ar</code>、<code>llvm-ranlib</code>、<code>llvm-nm</code>、<code>llvm-objcopy</code>、<code>llvm-objdump</code>、<code>llvm-readelf</code>、<code>llvm-strip</code>、<code>llvm-addr2line</code> 与 <code>llvm-dlltool</code>；在 MinGW 目标平台上将 RC 编译器设为 <code>llvm-windres</code>；在 macOS 目标平台上设置 Objective-C 编译器（clang 与 clang++）以及 <code>llvm-libtool-darwin</code>、<code>llvm-lipo</code> 和 <code>llvm-install-name-tool</code>（Apple 自带的 <code>libtool</code> 无法读取高版本 LLVM 生成的 bitcode）。</p><p>当构建非当前主机的 Linux 或 Windows 目标平台时，它还会设置 <code>CMAKE_SYSTEM_NAME</code>、<code>CMAKE_SYSTEM_PROCESSOR</code>、<code>CMAKE_&lt;LANG&gt;_COMPILER_TARGET</code> 与 <code>CMAKE_SYSROOT</code>（指向目标平台的 sysroot），并将 <code>CMAKE_FIND_ROOT_PATH_MODE_{LIBRARY,INCLUDE,PACKAGE}</code> 设为 <code>ONLY</code>，使库文件、头文件和包仅在 sysroot 内搜索，而可执行程序仍在主机上查找。在 macOS 主机上构建另一个 macOS 架构则会设置 <code>CMAKE_OSX_ARCHITECTURES</code>，CMake 不将其视为交叉编译。编译器实际使用的 sysroot、C++ 标准库、运行时库和链接器均由目标平台的配置文件指定，而非由工具链文件直接传入。</p><p>在 Linux 或 macOS 主机上构建 MSVC 目标平台时，如果工具链的 <code>sdk/windows</code> 下没有对应目标平台的 SDK，配置会立即报错停止；在未下载 SDK 的 Windows 主机上，clang 会自动查找本机安装的 Visual Studio。它会将 RC 编译器设为 <code>llvm-rc</code>，由 CMake 对目标平台 clang 预处理后的输出运行。若未显式设置，<code>CMAKE_MSVC_RUNTIME_LIBRARY</code> 默认为 <code>MultiThreaded</code>；使用 <code>MultiThreadedDebug</code> 或 <code>MultiThreadedDebugDLL</code> 链接时会自动传入 <code>/nodefaultlib:ucrt.lib</code>。除在 Windows 主机上构建本机架构（CMake 不视为交叉构建）或未下载 SDK 的情况外，SDK 路径都会加入 <code>CMAKE_FIND_ROOT_PATH</code>。</p><p>在 Linux 或 Windows 主机上构建 macOS 目标平台时，<code>CMAKE_OSX_SYSROOT</code> 优先取已指定的值，其次取 <code>SDKROOT</code>，再其次取工具链的 <code>sdk/macos</code>（若此处没有 SDK 则停止配置）。它会将 <code>CMAKE_SYSTEM_NAME</code> 设为 <code>Darwin</code>，将 <code>CMAKE_SYSTEM_PROCESSOR</code> 与 <code>CMAKE_OSX_ARCHITECTURES</code> 设为 <code>arm64</code> 或 <code>x86_64</code>，为 C、C++、ASM 与 Objective-C 设置 <code>CMAKE_&lt;LANG&gt;_COMPILER_TARGET</code>，并将 SDK 加入 <code>CMAKE_FIND_ROOT_PATH</code>（搜索模式同上）。</p><h3 id="从源码构建运行时库" tabindex="-1">从源码构建运行时库 <a class="header-anchor" href="#从源码构建运行时库" aria-label="Permalink to &quot;从源码构建运行时库&quot;">​</a></h3><p>由工具链文件引入的 <code>runtimes.cmake</code> 会读取以下变量（<a href="./../features/runtimes-from-source">从源码构建运行时库</a>）：</p><table tabindex="0"><thead><tr><th>变量</th><th></th></tr></thead><tbody><tr><td><code>XCLANG_RUNTIMES</code></td><td>默认为 <code>prebuilt</code>：使用工具链预编译的运行时库。设为 <code>source</code> 时：在首次请求对应变体的配置阶段，使用工具链的 <code>libc++/src</code> 配合下方选项为目标平台编译 libc++（含 libc++abi）、libc++experimental 与 libunwind；当前构建中的所有编译和链接（包括 <code>try_compile</code>）都会改用它们替代预编译版本。不支持 MSVC 目标平台</td></tr><tr><td><code>XCLANG_SANITIZER</code></td><td>由 <code>address</code>、<code>memory</code>、<code>thread</code>、<code>undefined</code>、<code>leak</code> 组成的列表：向构建中的每次编译和链接添加 <code>-fsanitize=</code>，并选用匹配的运行时库。配合预编译运行时库使用时，<code>address</code> 会在支持的目标平台上启用 ASan libc++，而 <code>memory</code> 会停止配置；配合 <code>source</code> 使用时，运行时库会带对应的 sanitizer 编译（<code>LLVM_USE_SANITIZER</code>：同时指定 ASan 与 UBSan 时一并启用，否则按 MemorySanitizer、ThreadSanitizer、UBSan、LeakSanitizer 的优先级择一启用），其中 <code>memory</code> 还会一并编译 compiler-rt 的 MemorySanitizer 运行时库并链接进可执行文件（<code>memory</code> 仅支持 glibc Linux 目标平台）。如果目标平台没有所请求 sanitizer 的运行时库，配置会报错停止：Windows 目标平台支持 <code>undefined</code> 及 x64 下的 <code>address</code>，musl 目标平台仅支持 <code>undefined</code></td></tr><tr><td><code>XCLANG_LIBCXX_HARDENING</code></td><td>可选 <code>none</code>、<code>fast</code>、<code>extensive</code> 或 <code>debug</code>：设置 libc++ 的加固模式（<code>LIBCXX_HARDENING_MODE</code>），同时作用于编译出的库代码与头文件的默认配置</td></tr><tr><td><code>XCLANG_LIBCXX_ABI_VERSION</code></td><td><code>1</code> 或 <code>2</code>（对应 <code>LIBCXX_ABI_VERSION</code>）</td></tr><tr><td><code>XCLANG_LIBCXX_ABI_NAMESPACE</code></td><td>libc++ 的内联 ABI 命名空间，格式为 <code>__&lt;name&gt;</code>（对应 <code>LIBCXX_ABI_NAMESPACE</code>）</td></tr><tr><td><code>XCLANG_LIBCXX_ABI_DEFINES</code></td><td>libc++ 的 ABI 宏列表，例如 <code>_LIBCPP_ABI_BOUNDED_ITERATORS</code>（对应 <code>LIBCXX_ABI_DEFINES</code>）</td></tr><tr><td><code>XCLANG_RUNTIMES_EXCEPTIONS</code></td><td>设为 <code>OFF</code> 或其他表示假的 CMake 布尔值时：在禁用异常的情况下构建 libc++ 与 libc++abi</td></tr><tr><td><code>XCLANG_RUNTIMES_RTTI</code></td><td>设为 <code>OFF</code> 或其他表示假的 CMake 布尔值时：在禁用 RTTI 的情况下构建 libc++；需同时设置 <code>XCLANG_RUNTIMES_EXCEPTIONS=OFF</code></td></tr><tr><td><code>XCLANG_RUNTIMES_FLAGS</code></td><td>编译 libc++ 与 libc++abi 的额外编译选项，例如 <code>-flto=thin</code></td></tr><tr><td><code>XCLANG_RUNTIMES_CMAKE_ARGS</code></td><td>传给运行时库 CMake 构建（LLVM 的 <code>runtimes/</code>）的额外参数，每项格式为 <code>-D&lt;variable&gt;=&lt;value&gt;</code></td></tr><tr><td><code>XCLANG_RUNTIMES_DIR</code></td><td>构建运行时库变体的目录，每个变体存放在 <code>&lt;target&gt;-&lt;digest&gt;</code> 子目录下；默认为 <code>${CMAKE_BINARY_DIR}/xclang-runtimes</code>，相对路径相对于构建目录解析</td></tr></tbody></table><p>除 <code>XCLANG_RUNTIMES</code> 与 <code>XCLANG_SANITIZER</code> 外，其余选项均需配合 <code>XCLANG_RUNTIMES=source</code> 使用。每个变体目录下包含其 CMake 构建树（<code>runtimes</code>，启用 MemorySanitizer 时还有 <code>compiler-rt</code>）、构建日志以及 <code>install</code> 安装目录：其中 <code>include/c++/v1</code> 包含 <code>__config_site</code> 等头文件，配合 <code>-nostdinc++</code> 排在目标平台配置文件的头文件之前；<code>lib</code> 包含库文件，链接时配合 <code>-nostdlib++</code>（除 macOS 及启用 sanitizer 的情况外，还会加上 <code>--unwindlib=none</code>）使用；<code>lib/libc++.modules.json</code> 与 <code>share/libc++/v1</code> 则提供 <code>xclang::std</code> 所需的模块文件。变体目录名包含由选项、目标平台和工具链计算出的摘要，因此同一变体在每个构建目录中只构建一次，修改选项后会在同级目录下构建新的变体。与上游 LLVM 构建一样，构建过程需要主机安装 Python 3。</p><h2 id="xclang-cmake" tabindex="-1"><code>xclang.cmake</code> <a class="header-anchor" href="#xclang-cmake" aria-label="Permalink to &quot;`xclang.cmake`&quot;">​</a></h2><p>从按版本标签检出的 FetchContent 目录中，在 <code>project()</code> 之前引入（完整示例见 <a href="./../integrations/cmake#without-xclang-installed">CMake</a>）：</p><div class="language-cmake vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cmake</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">include</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">${xclang_SOURCE_DIR}</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/packages/cmake/xclang.cmake)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>变量</th><th></th></tr></thead><tbody><tr><td><code>XCLANG_VERSION</code></td><td>要下载的版本号；未设置时取当前检出所对应的版本标签</td></tr><tr><td><code>XCLANG_TARGET</code></td><td>要构建的其他目标平台，用法与 <code>toolchain.cmake</code> 相同</td></tr><tr><td><code>XCLANG_ROOT</code></td><td>直接使用指定的已解压 xclang 工具链，不再下载</td></tr><tr><td><code>XCLANG_CACHE_DIR</code></td><td>解压工具链的缓存目录，按 <code>&lt;version&gt;/&lt;host&gt;</code> 存放（也可通过同名环境变量设置）；在 Linux 上默认为 <code>$XDG_CACHE_HOME/xclang</code> 或 <code>~/.cache/xclang</code>，在 macOS 上为 <code>~/Library/Caches/xclang</code>，在 Windows 上为 <code>%LOCALAPPDATA%\\xclang</code></td></tr><tr><td><code>XCLANG_URL</code></td><td>下载 <code>SHA256SUMS</code> 与压缩包的发布镜像地址；设置后将以镜像站上的 <code>SHA256SUMS</code> 为准</td></tr></tbody></table><p>它会验证服务器证书并下载对应版本的 <code>SHA256SUMS</code> 与主机压缩包 <code>xclang-&lt;version&gt;-&lt;host&gt;.tar.xz</code>，再对照校验行验证压缩包摘要。压缩包会先解压到临时目录，再原子移入缓存目录，避免多个构建树同时配置时发生冲突，随后自动设置 <code>CMAKE_TOOLCHAIN_FILE</code>。如果当前构建已经设置了工具链文件（例如 vcpkg 的工具链文件），它会报错停止；此时应改为通过 vcpkg 的 <code>VCPKG_CHAINLOAD_TOOLCHAIN_FILE</code> 链式加载 xclang 的工具链文件。构建目录会固定首次配置时的工具链文件：当版本号、<code>XCLANG_ROOT</code> 或 <code>XCLANG_CACHE_DIR</code> 发生变化时，它会在下载前报错停止，提示换用新构建目录或运行 <code>cmake --fresh</code>。</p><h2 id="libclang-的-cmake-包" tabindex="-1">libclang 的 CMake 包 <a class="header-anchor" href="#libclang-的-cmake-包" aria-label="Permalink to &quot;libclang 的 CMake 包&quot;">​</a></h2><p>libclang 压缩包内含 LLVM 与 clang 自身的 CMake 包（可通过 <code>find_package(Clang)</code> 查找），同时包含记录构建配置的 <code>lib/cmake/xclang/libclang.cmake</code>，提供 <code>XCLANG_LLVM_VERSION</code>、<code>XCLANG_LTO</code>、<code>XCLANG_PGO</code>、<code>XCLANG_PATCHES</code> 等变量（<a href="./../features/libclang">libclang</a>）。</p>',27)])])}const h=d(a,[["render",l]]);export{g as __pageData,h as default};
